/** Analysis-range cards use the real workbench with retained observations and controlled model admission. */
async page => {
  const assert = (condition, message) => { if (!condition) throw new Error(message) }
  const errors = [], onError = error => errors.push(error.message)
  page.on('pageerror', onError)
  const media = route => route.fulfill({ status: 200, contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="800" height="600" fill="#405852"/></svg>' })
  await page.route('**/api/visual-curator/resource**', media)
  const dialog = page.getByRole('dialog', { name: '选择本次分析范围', exact: true })
  try {
    await page.setViewportSize({ width: 1440, height: 900 })
    await page.reload()
    await page.waitForFunction(() => window.incrementalFixture.state.statusReads >= 1)
    const initialReads = await page.evaluate(() => { window.incrementalFixture.state.holdStatus = true; return window.incrementalFixture.state.statusReads })
    await page.locator('.vc-profile-actions').getByRole('button', { name: '继续分析', exact: true }).click()
    await dialog.waitFor()
    assert(await dialog.locator('.vc-analysis-scope-option').count() === 2, 'Both analysis ranges must remain available')
    assert(await page.evaluate(() => window.incrementalFixture.state.statusReads) === initialReads, 'Opening a current range must not start another Host request')
    assert(await dialog.locator('.vc-analysis-plan-loading').count() === 0, 'A confirmed range must render directly without a loading skeleton')
    const pendingRoles = await dialog.locator('.vc-analysis-scope-option').first().locator('.vc-analysis-scope-roles').textContent(), allRoles = await dialog.locator('.vc-analysis-scope-option').last().locator('.vc-analysis-scope-roles').textContent()
    assert(pendingRoles.includes('正例参考 0') && pendingRoles.includes('反例参考 1'), 'The pending range must show its own positive and negative images')
    assert(allRoles.includes('正例参考 1') && allRoles.includes('反例参考 1'), 'The full range must include both saved and new roles')
    await page.evaluate(() => window.incrementalFixture.releaseStatus())
    await page.waitForFunction(() => { const image = document.querySelector('.vc-analysis-scope-art'); return image?.complete && image.naturalWidth === 480 })
    assert((await dialog.innerText()).includes('已分析 1') && (await dialog.innerText()).includes('未分析 1'), 'The cards must use current saved and pending counts')
    assert((await dialog.innerText()).includes('整理阶段仍可能调用模型'), 'Reusing observations must retain the summary-call disclosure')
    await dialog.screenshot({ path: '.playwright-mcp/analysis-scope-redesigned-dark.png', animations: 'disabled' })
    await dialog.getByRole('button', { name: '分析待处理图片 1', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    await page.locator('.vc-profile-actions').getByRole('button', { name: '重新分析', exact: true }).click()
    await dialog.waitFor()
    const all = dialog.getByRole('button', { name: '全部重新分析 2', exact: true })
    assert(await all.getAttribute('data-preferred') === 'true', 'Explicit reanalysis must retain its preferred range')
    await all.click()
    await dialog.waitFor({ state: 'hidden' })
    await page.locator('.vc-profile-actions').getByRole('button', { name: '重新分析', exact: true }).click()
    await dialog.waitFor()
    for (const dark of [true, false]) {
      await page.setViewportSize({ width: 390, height: 844 })
      await page.evaluate(dark => window.incrementalFixture.theme(dark), dark)
      const fits = await dialog.evaluate(element => { const r=element.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight&&element.scrollWidth<=element.clientWidth+1 })
      assert(fits, 'Scope choices must remain readable within narrow light and dark viewports')
      if (!dark) await dialog.screenshot({ path: '.playwright-mcp/analysis-scope-redesigned-light-narrow.png', animations: 'disabled' })
    }
    await dialog.getByRole('button', { name: '取消', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    await page.setViewportSize({ width: 1440, height: 900 })
    const previousReads = await page.evaluate(() => { window.incrementalFixture.state.holdStatus = true; const reads = window.incrementalFixture.state.statusReads; window.incrementalFixture.advance(); return reads })
    await page.waitForFunction(previous => window.incrementalFixture.state.statusReads === previous + 1, previousReads)
    await page.locator('.vc-profile-actions').getByRole('button', { name: '重新分析', exact: true }).click()
    await dialog.locator('.vc-analysis-plan-loading').waitFor()
    assert(await page.evaluate(() => window.incrementalFixture.state.statusReads) === previousReads + 1, 'An opening range must share the already pending collection read')
    await dialog.getByRole('button', { name: '取消', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    await page.evaluate(() => window.incrementalFixture.releaseStatus())
    await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))))
    assert(!await dialog.isVisible(), 'A cancelled range must remain closed when the shared read completes')
    await page.locator('.vc-profile-actions').getByRole('button', { name: '重新分析', exact: true }).click()
    await dialog.waitFor()
    assert(await dialog.locator('.vc-analysis-scope-option').count() === 2, 'The completed shared read must remain usable after cancellation')
    assert(await page.evaluate(() => window.incrementalFixture.state.statusReads) === previousReads + 1, 'Reopening after a completed read must not refetch it')
    await dialog.getByRole('button', { name: '取消', exact: true }).click()
    const beforeFailure = await page.evaluate(() => { window.incrementalFixture.state.statusFailure = true; const count = window.incrementalFixture.state.statusReads; window.incrementalFixture.advance(); return count })
    await page.waitForFunction(previous => window.incrementalFixture.state.statusReads === previous + 1, beforeFailure)
    await page.evaluate(() => { window.incrementalFixture.state.statusFailure = false })
    await page.locator('.vc-profile-actions').getByRole('button', { name: '重新分析', exact: true }).click()
    await dialog.locator('.vc-analysis-scope-option').first().waitFor()
    assert(await page.evaluate(() => window.incrementalFixture.state.statusReads) === beforeFailure + 2, 'A failed read must be retried rather than remaining a rejected shared promise')
    await dialog.getByRole('button', { name: '取消', exact: true }).click()
    const launches = await page.evaluate(() => window.incrementalFixture.state.launches)
    assert(JSON.stringify(launches.map(item => item.analysisMode)) === JSON.stringify(['pending', 'all']), 'Each card must dispatch its stated analysis range once')
    assert(launches.every(item => item.buildDataset === true && item.planDigest === 'confirmed-plan'), 'Both choices must retain the confirmed plan')
    assert(errors.length === 0, 'Scope interaction must not produce browser errors')
    const result = { choices: 2, saved: 1, pending: 1, total: 2, analysisModes: ['pending', 'all'], cancelStartsNoTask: true, artworkLoaded: true, summaryCallDisclosed: true, narrowOverflow: false, themes: ['dark', 'light'], currentPlanOpensWithoutRead: true, sharedInFlightRead: true, cancellationKeepsBackgroundRead: true, roleCountsByRange: true, failedReadCanRetry: true, pageErrors: errors }
    const expected = await page.evaluate(async () => (await fetch('/analysis-scope-ui.expected.json')).json())
    assert(JSON.stringify(result) === JSON.stringify(expected), 'Analysis scope output differs from the expected user flow')
    return result
  } finally { page.off('pageerror', onError); await page.unroute('**/api/visual-curator/resource**', media) }
}
